const input = $input.first().json || {};
const body = input.body || {};
const headers = input.headers || {};
const provided = String(headers['x-webhook-secret'] || '');
const expected = String($env.INTERNAL_WEBHOOK_SECRET || '');
if (expected && provided !== expected) {
  throw new Error('Unauthorized: invalid X-Webhook-Secret');
}
const start = new Date(body.start_date);
const end = new Date(body.end_date);
const computed = Math.round((end - start) / 86400000) + 1;
const days = Number(body.duration_days) || (Number.isFinite(computed) ? computed : 1);
return [{ json: {
  trip_id: body.trip_id,
  generation_id: body.generation_id,
  callback_url: body.callback_url,
  weather_url: body.weather_url,
  origin: body.origin,
  destination: body.destination,
  start_date: body.start_date,
  end_date: body.end_date,
  duration_days: days,
  traveller_count: body.traveller_count || 1,
  budget: body.budget,
  currency: body.currency || 'INR',
  preferences: body.preferences || '',
  transport_preference: body.transport_preference || 'any',
  accommodation_preference: body.accommodation_preference || 'any',
  latitude: body.latitude != null ? Number(body.latitude) : null,
  longitude: body.longitude != null ? Number(body.longitude) : null,
  user_stops: Array.isArray(body.user_stops) ? body.user_stops : []
}}];

const base = $('Validate & Prepare').first().json;
const input = $input.first().json || {};
let latitude = base.latitude;
let longitude = base.longitude;
let resolved_name = base.destination;
const feature = input.features && input.features[0];
if ((latitude == null || longitude == null) && feature && feature.properties) {
  const p = feature.properties;
  if (p.lat != null && p.lon != null) {
    latitude = Number(p.lat);
    longitude = Number(p.lon);
  }
  resolved_name = p.city || p.name || p.formatted || resolved_name;
}
return [{ json: Object.assign({}, base, { latitude, longitude, resolved_name }) }];

const base = $('Merge Geocode').first().json;
const input = $input.first().json || {};
const places = [];
for (const f of (input.features || [])) {
  const p = f.properties || {};
  const c = (f.geometry && f.geometry.coordinates) || [];
  const lat = p.lat != null ? Number(p.lat) : (c.length > 1 ? Number(c[1]) : null);
  const lon = p.lon != null ? Number(p.lon) : (c.length > 0 ? Number(c[0]) : null);
  if (p.name && Number.isFinite(lat) && Number.isFinite(lon)) {
    places.push({ name: p.name, category: (p.categories || [])[0] || '', lat, lon });
  }
}
return [{ json: Object.assign({}, base, { places }) }];

const base = $('Merge Places').first().json;
const input = $input.first().json || {};
let weather = null;
let weather_message = null;
if (input.daily && Array.isArray(input.daily.time)) {
  const daily = [];
  for (let i = 0; i < input.daily.time.length; i++) {
    const date = input.daily.time[i];
    if (date < base.start_date || date > base.end_date) continue;
    daily.push({
      date,
      temp_max_c: input.daily.temperature_2m_max ? input.daily.temperature_2m_max[i] : null,
      temp_min_c: input.daily.temperature_2m_min ? input.daily.temperature_2m_min[i] : null,
      precip_prob_max: input.daily.precipitation_probability_max ? input.daily.precipitation_probability_max[i] : null,
      weather_code: input.daily.weather_code ? input.daily.weather_code[i] : null
    });
  }
  if (daily.length) {
    const cur = input.current || {};
    weather = {
      location_name: base.resolved_name || base.destination,
      current: cur.temperature_2m != null ? {
        temperature_c: cur.temperature_2m,
        weather_code: cur.weather_code != null ? cur.weather_code : null,
        observed_at: null
      } : null,
      daily
    };
  } else {
    weather_message = 'Forecast is only available within 16 days of travel.';
  }
} else {
  weather_message = 'Weather forecast unavailable right now.';
}
return [{ json: Object.assign({}, base, { weather, weather_message }) }];

const base = $('Merge Weather').first().json;
const input = $input.first().json || {};
const coord = v => {
  if (v == null || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};
let text = '';
try {
  text = (input.candidates[0].content.parts || []).map(p => p.text || '').join('');
} catch (e) {
  text = '';
}
if (!text) throw new Error('Gemini returned no content');
text = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let data;
try {
  data = JSON.parse(text);
} catch (e) {
  throw new Error('Gemini returned invalid JSON');
}
const maxDay = Math.max(1, Number(base.duration_days) || 1);
const itinerary = (Array.isArray(data.itinerary) ? data.itinerary : []).map((r, i) => {
  const rawDay = Number(r.day_number);
  const day = Number.isFinite(rawDay) ? Math.min(maxDay, Math.max(1, Math.round(rawDay))) : 1;
  const start = /^\d{1,2}:\d{2}$/.test(String(r.start_time || '')) ? r.start_time : null;
  const end = /^\d{1,2}:\d{2}$/.test(String(r.end_time || '')) ? r.end_time : null;
  return {
    day_number: day,
    activity_name: String(r.activity_name || '').trim(),
    description: r.description || null,
    location: r.location || null,
    start_time: start,
    end_time: end,
    estimated_cost: r.estimated_cost != null ? String(r.estimated_cost) : '0.00',
    latitude: coord(r.latitude),
    longitude: coord(r.longitude),
    sort_order: Number.isFinite(Number(r.sort_order)) ? Number(r.sort_order) : i
  };
}).filter(r => r.activity_name);
if (!itinerary.length) throw new Error('Gemini returned no valid activities');
const expenses = (Array.isArray(data.expenses) ? data.expenses : []).map(r => ({
  category: String(r.category || 'misc'),
  description: r.description || null,
  amount: r.amount != null ? String(r.amount) : null
})).filter(r => r.amount && Number(r.amount) > 0);
const days = (Array.isArray(data.days) ? data.days : []).map(r => ({
  day_number: Number(r.day_number) || 1,
  title: r.title || null,
  summary: r.summary || null,
  stop_name: r.stop_name || null
}));
const stops = (Array.isArray(data.stops) ? data.stops : []).map(r => ({
  name: String(r.name || '').trim(),
  latitude: coord(r.latitude),
  longitude: coord(r.longitude)
})).filter(r => r.name);
const payload = {
  generation_id: base.generation_id,
  status: 'Completed',
  itinerary,
  days,
  expenses,
  stops,
  latitude: base.latitude != null ? base.latitude : null,
  longitude: base.longitude != null ? base.longitude : null,
  hero_quote: data.hero_quote ? String(data.hero_quote).slice(0, 200) : null,
  hero_quote_author: data.hero_quote_author ? String(data.hero_quote_author).slice(0, 80) : null
};
if (base.weather) {
  payload.weather = base.weather;
} else if (base.weather_message) {
  payload.weather = {
    location_name: base.resolved_name || base.destination,
    current: null,
    daily: [],
    weather_message: base.weather_message
  };
}
return [{ json: { callback_url: base.callback_url, payload } }];

const base = $('Validate & Prepare').first().json;
const input = $input.first().json || {};
let message = 'Itinerary generation failed. Please retry.';
if (input.error) {
  message = input.error.message || input.error.description || String(input.error);
} else if (input.message) {
  message = input.message;
}
return [{ json: { callback_url: base.callback_url, payload: {
  generation_id: base.generation_id,
  status: 'Failed',
  error_message: String(message).slice(0, 500)
} } }];
